import net from 'node:net';
function main(): void {
  const server = net.createServer((s: any) => { s.on('error', () => {}); s.end('hi'); });
  server.listen(0, '127.0.0.1', () => {
    const port = (server.address() as any).port;
    const c: any = net.connect({ port: port, host: '127.0.0.1', allowHalfOpen: true });
    let got = '';
    c.on('data', (d: any) => { got += d; });
    c.on('end', () => { console.log('end', c.writable, got); c.end(); });
    c.on('close', () => {
      console.log('client closed');
      const c2: any = net.connect(port, '127.0.0.1');
      c2.on('error', () => {});
      c2.on('connect', () => { console.log(c2.resetAndDestroy() === c2); });
      c2.on('close', () => { console.log('c2 closed'); server.close(); });
    });
  });
}
